import logging
import pprint
import json
import six
from threading import Lock

from ute_common_abstract_core import logger as core_logging
from ute_common_abstract_core.notifying_creator import NotifyingCreator
from ute_common_abstract_core.network_elem_identification import UeIdentification, CellIdentification, MmeIdentification
from ta_messaging.exceptions import TranslationOfMessageTypeToAsnNotPossible
from ta_messaging.message_sources import message_source_base
from ta_messaging.unparsed_message import UnparsedMessage
from ta_ue_plugin_rtg.messaging.message_types import message_types
from ta_ue_plugin_rtg.messaging.message_parser import RtgMessageParser


class RtgMessageSource(message_source_base.MessageSource):
    """Message source extracting unparsed messages from data stream of RTG Ue simulator"""
    _instance = None
    _instance_lock = Lock()

    def __new__(cls, *args, **kwargs):
        with cls._instance_lock:
            if cls._instance is None:
                cls._instance = super(RtgMessageSource, cls).__new__(cls)
        return cls._instance

    def __init__(self, queue, data_stream, variant):
        """
        :param queue: Queue instance
        :param data_stream: object to connect produces messages
        """
        if not getattr(self, '_initialized', False):
            super(RtgMessageSource, self).__init__(queue)
            self.data_stream = data_stream
            self.variant = variant
            self._buffered_data = ''
            self.message_iterator = self._read()
            self._initialized = True
        else:
            if self.variant != variant:
                raise RuntimeError("CUS and RTG types cannot be used both in single python session")
        if not getattr(self, '_started', False):
            self._started = True
            self._start_in_separate_thread()

    def start(self):
        """
        Starts MessageSource infinite loop.
        Infinite loop is composed of parsing data stream, creating UnparsedMessages
        and sending them to the output queue
        """
        self.data_stream = self._get_opened_connection()
        super(RtgMessageSource, self).start()

    def stop(self):
        """Stops message source loop and performs cleanup"""
        self._close_connection()
        if self.is_running.is_set():
            self.is_running.clear()
            self._main_loop_finished.acquire()
        self.logger.debug('%s stopped' % self)
        self._started = False

    # --- required API methods

    def _src_name(self):
        """
        Message source name to be used for identifying it inside logs.
        Also used to construct filename of log per message source so, make it short.
        """
        return 'rtg-msgs'

    def _read(self):
        """
        Iterate all valid protocol data combined from UEsim console
        :return: iterator with protocol data
        """
        chunk = self.data_stream.read()
        while True:
            if chunk is None:
                yield None
            else:
                recv_data = chunk.splitlines()
                if recv_data:
                    recv_data = [self._buffered_data + recv_data[0]] + recv_data[1:]
                    self._buffered_data = ''
                    for message in self._parse_recived_data(recv_data):
                        yield message
            chunk = self.data_stream.read()

    def _parse_recived_data(self, recv_data):
        """
        Convert string into list of JSONs and buffer part of the message if an incomplete message was found at the end of the recived data.
        :return: list of messages as dict objects
        """
        parsed_msg_list = []
        for message in recv_data:
            try:
                message_data = json.loads(message)
                parsed_msg_list.append(message_data)
            except ValueError:
                if recv_data[-1] == message and message.startswith('{') and not message.endswith('}'):
                    self._buffered_data = message
                else:
                    self.logger.warning('invalid JSON message recived: {}'.format(message))
        return parsed_msg_list

    def _get_protocol_data(self):
        """
        Return valid protocol data combined from UEsim console

        Valid data encapsulate whole messages - truncation is forbidden
        Goal of this method is to find message boundaries within data stream
        and extract that whole message (without parsing yet)

        returning None indicates end-of-data (or end of its processing) and will close message source

        :return: protocol data
        """
        return next(self.message_iterator)

    def _get_unparsed_messages(self, protocol_data):
        """
        Returns list of unparsed_messages extracted from protocol_data

        :param protocol_data: data chunks that encapsulated whole messages
        :return: list of UnparsedMessage instances
        """
        self.logger.log(core_logging.RAW_DATA, protocol_data)
        try:
            msg_type = protocol_data["msg_type"]
        except KeyError:
            return []

        self.logger.debug('{} << Packet {} arrived'.format(self, msg_type))
        occurrence_time = self._get_value_under_key(protocol_data, "occurrence_time")
        msg_owner = self._get_message_owner(protocol_data)

        if msg_type in message_types:
            asn1_message_type = message_types[msg_type]
            self.logger.debug("{}: {} '{}' {}".format("UnparsedMessage", "Message", asn1_message_type, "recognized"))
        elif msg_type in list(message_types.values()):
            asn1_message_type = msg_type
            self.logger.debug("{}: {} '{}' {}".format("UnparsedMessage", "Message", asn1_message_type, "recognized"))
        else:
            # need to create UnparsedMessage instance
            asn1_message_type = msg_type

            # log error but allow to proceed!
            err = TranslationOfMessageTypeToAsnNotPossible('Message {} could not be recognized'
                                                           .format(pprint.pformat(msg_type)))
            error_msg = str(err)
            self.logger.error(error_msg)
            messaging_logger = logging.getLogger('messaging')
            messaging_logger.error(error_msg)

        unparsed_msg_instance = UnparsedMessage(owner=msg_owner,
                                                msg_payload=protocol_data["msg_payload"],
                                                message_type=asn1_message_type,
                                                parser=RtgMessageParser(),
                                                meta_data_dict={'occurrence_time': occurrence_time,
                                                                'hex': protocol_data,
                                                                'protocol': protocol_data["protocol"],
                                                                'pdu_type': protocol_data["pdu_type"]})
        return [unparsed_msg_instance]

    def _get_opened_connection(self):
        """
        Returns data stream that has been "opened"

        Open here represents some connect-process after which we can read data from that data stream.
        Such opening/connecting process might be as simple as opening local file storing "data to read".
        It may also involve establishing remote host connection or connection towards some process.

        :return: connection
        """
        if self.data_stream.closed:
            self.data_stream.open()
        return self.data_stream

    def _close_connection(self):
        """
        Closes data stream - no more read() possible from that data stream.

        In case of data stream from remote machine it closes connection to that remote.

        :return: None
        """
        self.data_stream.close()

    def _get_message_owner(self, message_data):
        """
        Msg owner_id may looks like: 2
        :return: UeIdentification intance with owner_name like: UE_2
        """
        owner_id = self._get_value_under_key(message_data, "owner_id")
        owner_type = self._get_value_under_key(message_data, "owner_type")

        identification = {"mme": MmeIdentification, "ue": UeIdentification, "cell": CellIdentification}.get(owner_type, None)

        class NotNotifyingCreator(NotifyingCreator):
            def __call__(cls, *args, **kwargs):
                return super(NotifyingCreator, cls).__call__(*args, **kwargs)  # pylint: disable=E1003

        @six.add_metaclass(NotNotifyingCreator)
        class MsgIdentification(identification):
            pass

        owner = MsgIdentification.from_type_id_pairs(identifiers=[(self.variant, owner_id)], specific_for_tool=self.variant)
        return owner

    def _get_value_under_key(self, msg_data, key):
        try:
            return msg_data[key]
        except KeyError:
            # msg_data structure:
            # %{
            #   protocol: protocol,
            #   occurrence_time: timestamp,
            #   owner_type: owner_type,
            #   owner_id: owner_id,
            #   pdu_type: pdu_type <> pdu_type_suffix,
            #   msg_type: msg_type,
            #   msg_payload: bin
            # }
            self.logger.debug('{} << Malformed packet arrived: {}'.format(self, msg_data))
            msg_data_mandatory_keys = ['protocol', 'occurrence_time', 'owner_type', 'owner_id', 'pdu_type', 'msg_type', 'msg_payload']
            malformed_keys = [u_key for u_key in msg_data.keys() if u_key not in msg_data_mandatory_keys]
            if len(malformed_keys) == 1:
                return msg_data[malformed_keys[0]]
            else:
                self.logger.debug('{} << Multiple malformed keys ({}) detected for msg: {}. {} filled with None'.
                                  format(self, malformed_keys, msg_data, key))
                return None
